// src/components/AdminHeader.jsx
import React, { useState } from "react";
import { Link } from "react-router-dom";
import ParentFeePage from "./ParentFeePage";
import "../styles/main.css";

export default function AdminHeader() {
  const [showFeePopup, setShowFeePopup] = useState(false);

  return (
    <>
      <header className="site-header">
        <div className="topbar">
          <div className="top-left">
            <img src="/assets/logo.png" alt="logo" className="logo" />
            <div className="school-meta">
              <div className="school-name">
                Kendriya Vidyalaya Sector-24 Noida
              </div>
              <div className="school-sub">
                CBSE Board Affiliated Co-Ed English Medium Senior Secondary School
              </div>
            </div>
          </div>

          <div className="top-right">
            {/* Fee Pay Button */}
            <button
              className="header-fee-btn"
              onClick={() => setShowFeePopup(true)}
            >
              💳 Fee Pay
            </button>

            <Link to="/" className="login-btn">
              Go to Website
            </Link>
          </div>
        </div>
      </header>

      {/* Popup Modal for Fee Pay */}
      {showFeePopup && (
        <div className="modal-overlay">
          <div className="modal-box">
            <button
              className="close-btn"
              onClick={() => setShowFeePopup(false)}
            >
              ✖
            </button>
            <ParentFeePage />
          </div>
        </div>
      )}
    </>
  );
}
